// P-code semantics check for the uPD78xx module. Reads test/emu/cases.txt (generated by
// test/emu/cases.py from cases.src; the code bytes come from the AS assembler, the expectations
// are worked out by hand from the manual), and for each case writes the code segments, sets
// registers and memory, emulates with Ghidra's EmulatorHelper from ram:1000 until the PC reaches
// the end address, and compares registers and memory.
// SP starts at 8000h, everything else at 0 unless the case sets it.
//
// Case file lines:
//   case <name>
//   code <hexaddr> <hexbytes>          (one or more segments)
//   end <hexaddr>                      (stop when the PC reaches it)
//   set <reg> <value> | set ram:<hexaddr>[/<n>] <value>   (n bytes, little-endian)
//   expect <reg> <value> | expect ram:<hexaddr>[/<n>] <value>
//   done
// Script args: <cases.txt> <outfile>
//@category Testing

import java.io.BufferedReader;
import java.io.FileReader;
import java.io.PrintStream;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import ghidra.app.emulator.EmulatorHelper;
import ghidra.app.script.GhidraScript;
import ghidra.program.model.address.Address;
import ghidra.program.model.address.AddressSet;

public class UpdEmuTest extends GhidraScript {

	private static class Case {
		String name;
		List<long[]> segAddr = new ArrayList<>();
		List<byte[]> segBytes = new ArrayList<>();
		long end;
		Map<String, Long> set = new LinkedHashMap<>();
		Map<String, Long> expect = new LinkedHashMap<>();
	}

	private List<Case> load(String path) throws Exception {
		List<Case> cases = new ArrayList<>();
		Case c = null;
		try (BufferedReader r = new BufferedReader(new FileReader(path))) {
			String line;
			while ((line = r.readLine()) != null) {
				line = line.trim();
				if (line.isEmpty() || line.startsWith("#")) {
					continue;
				}
				String[] f = line.split("\\s+");
				switch (f[0]) {
					case "case":
						c = new Case();
						c.name = f[1];
						break;
					case "code": {
						byte[] b = new byte[f[2].length() / 2];
						for (int i = 0; i < b.length; i++) {
							b[i] = (byte) Integer.parseInt(f[2].substring(2 * i, 2 * i + 2), 16);
						}
						c.segAddr.add(new long[] { Long.parseLong(f[1], 16) });
						c.segBytes.add(b);
						break;
					}
					case "end":
						c.end = Long.parseLong(f[1], 16);
						break;
					case "set":
						c.set.put(f[1], Long.decode(f[2]));
						break;
					case "expect":
						c.expect.put(f[1], Long.decode(f[2]));
						break;
					case "done":
						cases.add(c);
						break;
					default:
						throw new IllegalArgumentException("bad line: " + line);
				}
			}
		}
		return cases;
	}

	private Address addr(long off) {
		return currentProgram.getAddressFactory().getDefaultAddressSpace().getAddress(off);
	}

	private Address memAddr(String loc) {
		String[] p = loc.split("[:/]");
		return addr(Long.parseLong(p[1], 16));
	}

	private int size(String loc) {
		String[] p = loc.split("/");
		return p.length > 1 ? Integer.parseInt(p[1]) : 1;
	}

	// The status byte (0 Z SK HC L1 L0 0 CY) is not a register of the language: every flag has its
	// own register. "PSW" in the case files is composed from / split into them.
	private static final String[] FLAGS = { "CY", null, "L0", "L1", "HC", "SK", "Z" };

	private void writePsw(EmulatorHelper emu, long v) {
		for (int i = 0; i < FLAGS.length; i++) {
			if (FLAGS[i] != null) {
				emu.writeRegister(FLAGS[i], (v >> i) & 1);
			}
		}
	}

	private long readPsw(EmulatorHelper emu) {
		long v = 0;
		for (int i = 0; i < FLAGS.length; i++) {
			if (FLAGS[i] != null) {
				v |= (emu.readRegister(FLAGS[i]).longValue() & 1) << i;
			}
		}
		return v;
	}

	private String runCase(Case c) throws Exception {
		Address start = addr(0x1000);
		Address end = addr(c.end);
		for (int i = 0; i < c.segAddr.size(); i++) {
			Address a = addr(c.segAddr.get(i)[0]);
			byte[] b = c.segBytes.get(i);
			clearListing(new AddressSet(a, a.add(b.length + 8)));
			setBytes(a, b);
		}
		final EmulatorHelper emu = new EmulatorHelper(currentProgram);
		try {
			emu.writeRegister("SP", 0x8000);
			writePsw(emu, 0);
			for (Map.Entry<String, Long> e : c.set.entrySet()) {
				if (e.getKey().startsWith("ram:")) {
					int n = size(e.getKey());
					byte[] b = new byte[n];
					for (int i = 0; i < n; i++) {
						b[i] = (byte) (e.getValue() >> (8 * i));
					}
					emu.writeMemory(memAddr(e.getKey()), b);
				}
				else if (e.getKey().equals("PSW")) {
					writePsw(emu, e.getValue());
				}
				else {
					emu.writeRegister(e.getKey(), e.getValue());
				}
			}
			emu.writeRegister(emu.getPCRegister(), start.getOffset());
			int steps = 0;
			while (!emu.getExecutionAddress().equals(end)) {
				if (++steps > 2000) {
					return "did not reach the end (pc " + emu.getExecutionAddress() + ")";
				}
				if (!emu.step(monitor)) {
					return "emulation error at " + emu.getExecutionAddress() + ": " +
						emu.getLastError();
				}
			}
			StringBuilder bad = new StringBuilder();
			for (Map.Entry<String, Long> e : c.expect.entrySet()) {
				long got;
				if (e.getKey().startsWith("ram:")) {
					int n = size(e.getKey());
					byte[] b = emu.readMemory(memAddr(e.getKey()), n);
					got = 0;
					for (int i = n - 1; i >= 0; i--) {
						got = (got << 8) | (b[i] & 0xff);
					}
				}
				else if (e.getKey().equals("PSW")) {
					got = readPsw(emu);
				}
				else {
					got = emu.readRegister(e.getKey()).longValue();
				}
				if (got != e.getValue()) {
					bad.append(String.format(" %s=0x%x (expected 0x%x)", e.getKey(), got,
						e.getValue()));
				}
			}
			return bad.length() == 0 ? null : bad.toString().trim();
		}
		finally {
			emu.dispose();
		}
	}

	@Override
	protected void run() throws Exception {
		String[] args = getScriptArgs();
		List<Case> cases = load(args[0]);
		PrintStream out = new PrintStream(args[1]);
		int pass = 0, fail = 0;
		for (Case c : cases) {
			String err = runCase(c);
			if (err == null) {
				pass++;
				out.println("PASS " + c.name);
			}
			else {
				fail++;
				out.println("FAIL " + c.name + ": " + err);
			}
		}
		out.printf("emulation (%s): %d passed, %d failed%n", currentProgram.getLanguageID(), pass,
			fail);
		out.close();
	}
}
